"use client";

/**
 * Moodboard: a headline carries one picture slot between its words. The slot
 * swaps pictures on the beat, then the camera flies into the last one until it
 * fills the frame as the hero shot.
 *
 * Written by Better Design. Painted from the theme prop; with no pictures the
 * slot shows landscape placeholders drawn from the primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, progress, shiftHue, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

/** A bare file name resolves from the project's public folder; a URL or root path passes through. */

const { fontFamily: INTER } = loadFont("normal", { weights: ["600", "700"], subsets: ["latin"] });

const FIRST_BEAT = 16;
/** Frames between two swaps. */
const BEAT = 9;
const PLACEHOLDERS = 6;
const SLOT_W = 288;
const SLOT_H = 162;
const FLY_FRAMES = 36;
/** The zoom at which the 16:9 slot covers the 1920 by 1080 frame. */
const FULL = 1920 / SLOT_W;

/** Fixed paper and ink for placeholder photos, so they read the same in both modes. */
const LIGHT = "oklch(0.97 0.015 85)";
const DEEP = "oklch(0.3 0.05 60)";

export interface MoodboardProps {
  /** Words before the picture slot. */
  before?: string;
  /** Words after the picture slot. */
  after?: string;
  /** Image URLs or static files, shown in order. The last one becomes the hero. */
  pictures?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

/** A landscape drawn from the theme, sized in percent so it holds at any zoom. */
function PlaceholderPhoto({ theme, index }: { theme: VideoTheme; index: number }) {
  const base = shiftHue(theme.primary, index * 53 - 40);
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", background: `linear-gradient(170deg, ${mix(base, LIGHT, 0.66)}, ${mix(base, LIGHT, 0.2)})` }}>
      <div style={{ position: "absolute", width: "18%", aspectRatio: "1", borderRadius: "50%", left: `${20 + (index * 29) % 52}%`, top: "14%", background: mix(base, LIGHT, 0.9) }} />
      <div style={{ position: "absolute", left: "-25%", right: "20%", bottom: "-46%", height: "90%", borderRadius: "50%", background: mix(base, DEEP, 0.26) }} />
      <div style={{ position: "absolute", left: "30%", right: "-35%", bottom: "-58%", height: "92%", borderRadius: "50%", background: mix(base, DEEP, 0.48) }} />
    </div>
  );
}

/** A headline whose picture slot swaps on the beat, then opens into a full-frame hero. */
export function Moodboard({
  before = "Make it",
  after = "yours",
  pictures = [],
  theme: themeOverride,
  font,
}: MoodboardProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const count = pictures.length > 0 ? pictures.length : PLACEHOLDERS;

  const flyAt = FIRST_BEAT + (count - 1) * BEAT + 18;
  const beat = Math.max(0, Math.min(count - 1, Math.floor((frame - FIRST_BEAT) / BEAT)));
  const sinceSwap = frame < FIRST_BEAT ? frame : frame - FIRST_BEAT - beat * BEAT;
  const pop = beat === 0 && frame < FIRST_BEAT ? 1 : interpolate(easings.out(progress(sinceSwap, 0, 7)), [0, 1], [1.12, 1]);

  const enter = easings.out(progress(frame, 0, 16));
  const slotIn = easings.overshoot(progress(frame, 4, 16));

  // Fly in on a log scale so every step of the zoom feels equally fast.
  const fly = easings.inOut(progress(frame, flyAt, FLY_FRAMES));
  const zoom = Math.exp(Math.log(FULL) * fly);
  const textFade = 1 - progress(fly, 0.15, 0.4);
  const radius = theme.radius * 1.6 * (1 - fly);
  const drift = 1 + 0.06 * (1 - easings.out(progress(frame, flyAt, FLY_FRAMES + 20)));

  const picture = (index: number) =>
    pictures.length > 0 ? (
      <Img src={srcOf(pictures[index])} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
    ) : (
      <PlaceholderPhoto theme={theme} index={index} />
    );

  const word = {
    flex: 1,
    fontSize: 128,
    fontWeight: 700,
    letterSpacing: "-0.04em",
    lineHeight: 1,
    color: theme.foreground,
    whiteSpace: "nowrap",
    opacity: textFade * enter,
  } as const;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: `scale(${zoom})`, transformOrigin: "960px 540px" }}>
        <AbsoluteFill style={{ flexDirection: "row", alignItems: "center", gap: 40, transform: `translateY(${(1 - enter) * 24}px)` }}>
          <div style={{ ...word, textAlign: "right" }}>{before}</div>
          <div
            style={{
              position: "relative",
              width: SLOT_W,
              height: SLOT_H,
              flexShrink: 0,
              borderRadius: radius,
              overflow: "hidden",
              background: theme.muted,
              transform: `scale(${slotIn})`,
              boxShadow: fly > 0 ? "none" : `0 18px 40px oklch(0 0 0 / 0.14)`,
            }}
          >
            <div style={{ position: "absolute", inset: 0, transform: `scale(${pop * drift})` }}>{picture(beat)}</div>
          </div>
          <div style={{ ...word, textAlign: "left" }}>{after}</div>
        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
}
